/// Lock a project with `tool.uv.override-dependencies` scoped to a package version.
#[cfg(feature = "test-universal")]
#[test]
fn lock_project_with_scoped_overrides() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio==3.7.0"]

        [tool.uv]
        override-dependencies = [
            "idna==3.1",
            # A bare override must remain a global override when round-tripping the lockfile.
            "sniffio",
            # The package-scoped override takes precedence for AnyIO's dependency.
            { package = { name = "anyio", version = "3.7.0" }, dependencies = ["idna==3.2"] },
        ]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(context.read("uv.lock"), @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [manifest]
        overrides = [
            { package = { name = "anyio", version = "3.7.0" }, dependencies = [{ name = "idna", specifier = "==3.2" }] },
            { name = "idna", specifier = "==3.1" },
            { name = "sniffio" },
        ]

        [[package]]
        name = "anyio"
        version = "3.7.0"
        source = { registry = "http://[LOCALHOST]/simple/" }
        dependencies = [
            { name = "idna" },
            { name = "sniffio" },
        ]
        sdist = { url = "http://[LOCALHOST]/files/anyio-3.7.0.tar.gz", hash = "sha256:c8f99c47f03aec932b6cee4178beb10ce5b0aaf6d3e1ff52cc5e49fc3186af0a", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/anyio-3.7.0-py3-none-any.whl", hash = "sha256:ea75fecadcfa9b11a8bfa2ff25ea52a2904950d4925ba758c97d97e32c314556", upload-time = "2024-03-24T00:00:00Z" },
        ]

        [[package]]
        name = "idna"
        version = "3.2"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/idna-3.2.tar.gz", hash = "sha256:123503216f90b6fe70799f63c2df20e1873d3cc9b9eec4679070e6e5dc8b0689", upload-time = "2021-05-29T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/idna-3.2-py3-none-any.whl", hash = "sha256:ba7047fe719d6337288b7e8f32c874a352a8461b5db9993040c42d1cc5fa8fa5", upload-time = "2021-05-29T00:00:00Z" },
        ]

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "anyio" },
        ]

        [package.metadata]
        requires-dist = [{ name = "anyio", specifier = "==3.7.0" }]

        [[package]]
        name = "sniffio"
        version = "1.3.1"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/sniffio-1.3.1.tar.gz", hash = "sha256:ce520d2eb3c2be02f0c148dab5ba304e8705e1c7e7b4bec8a9146c464a597a6a", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/sniffio-1.3.1-py3-none-any.whl", hash = "sha256:2743fa2a853c508a2310882c0b4104631e0b0fcb855e00a912b7e3f27e6b3f05", upload-time = "2024-03-24T00:00:00Z" },
        ]
        "#);
    });

    uv_snapshot!(context.filters(), context.lock().arg("--locked"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    uv_snapshot!(context.filters(), context.sync().arg("--frozen"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Prepared 3 packages in [TIME]
    Installed 3 packages in [TIME]
     + anyio==3.7.0
     + idna==3.2
     + sniffio==1.3.1
    ");

    // A package-scoped override does not replace a direct requirement for the same dependency.
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio==3.7.0", "idna==3.6"]

        [tool.uv]
        override-dependencies = [
            { package = { name = "anyio", version = "3.7.0" }, dependencies = ["idna==3.2"] },
        ]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 1 (failure)
    ----- stderr -----
    error: No solution found when resolving dependencies
      cause: Because anyio==3.7.0 depends on idna==3.2 and your project depends on anyio==3.7.0, we can conclude that your project depends on idna==3.2.
             And because your project depends on idna==3.6, we can conclude that your project's requirements are unsatisfiable.
    ");

    // A version-gated override is ignored for other versions of the parent package.
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio==3.7.0", "idna==3.6"]

        [tool.uv]
        override-dependencies = [
            { package = { name = "anyio", version = "3.6.2" }, dependencies = ["idna==3.2"] },
        ]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 4 packages in [TIME]
    Updated idna v3.2 -> v3.6
    ");

    uv_snapshot!(context.filters(), context.sync().arg("--frozen"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Prepared 1 package in [TIME]
    Uninstalled 1 package in [TIME]
    Installed 1 package in [TIME]
     - idna==3.2
     + idna==3.6
    ");

    Ok(())
}

/// Reject conflicting overrides scoped to the same package version.
#[cfg(feature = "test-universal")]
#[test]
fn lock_project_with_conflicting_scoped_overrides() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio==3.7.0"]

        [tool.uv]
        override-dependencies = [
            { package = { name = "anyio", version = "3.7.0" }, dependencies = ["idna==3.2"] },
            { package = { name = "anyio", version = "3.7.0" }, dependencies = ["idna==3.3"] },
        ]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 1 (failure)
    ----- stderr -----
    error: No solution found when resolving dependencies
      cause: Because anyio==3.7.0 depends on idna==3.2 and idna==3.3, we can conclude that anyio==3.7.0 cannot be used.
             And because your project depends on anyio==3.7.0, we can conclude that your project's requirements are unsatisfiable.
    ");

    Ok(())
}

