/// `--upgrade --dry-run` should not report changes when the lockfile is up-to-date with
/// fork markers.
///
/// Regression test for: <https://github.com/astral-sh/uv/issues/16839>
#[cfg(feature = "test-universal")]
#[test]
fn lock_upgrade_dry_run_multi_version() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = [
            "markupsafe<2 ; sys_platform != 'win32'",
            "markupsafe==2.0.0 ; sys_platform == 'win32'"
        ]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 3 packages in [TIME]
    ");

    uv_snapshot!(context.filters(), context.lock().arg("--upgrade").arg("--dry-run"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 3 packages in [TIME]
    No lockfile changes detected
    ");

    Ok(())
}

/// `--check --refresh` should not report changes when the lockfile is already
/// canonical for workspace conflicts.
///
/// Regression test for: <https://github.com/astral-sh/uv/issues/18553>
#[cfg(feature = "test-universal")]
#[test]
fn lock_check_refresh_workspace_conflicts() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "workspace-demo"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["package-a"]

        [project.optional-dependencies]
        prod = ["package-a[prod]"]
        non-prod = ["package-a[non-prod]"]

        [tool.uv.workspace]
        members = ["packages/package-a"]

        [tool.uv.sources]
        package-a = { workspace = true }

        [tool.uv]
        conflicts = [
            [
                { extra = "prod" },
                { extra = "non-prod" },
            ],
        ]
        "#,
    )?;

    let package_dir = context.temp_dir.child("packages").child("package-a");
    package_dir.create_dir_all()?;
    package_dir.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "package-a"
        version = "0.1.0"
        requires-python = ">=3.12"

        [project.optional-dependencies]
        prod = ["sortedcontainers==2.3.0"]
        non-prod = ["sortedcontainers==2.4.0"]

        [tool.uv]
        conflicts = [
            [
                { extra = "prod" },
                { extra = "non-prod" },
            ],
        ]

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
        "#,
    )?;

    context.lock().assert().success();
    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"
        conflicts = [[
            { package = "package-a", extra = "non-prod" },
            { package = "package-a", extra = "prod" },
        ], [
            { package = "workspace-demo", extra = "non-prod" },
            { package = "workspace-demo", extra = "prod" },
        ]]

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [manifest]
        members = [
            "package-a",
            "workspace-demo",
        ]

        [[package]]
        name = "package-a"
        version = "0.1.0"
        source = { editable = "packages/package-a" }

        [package.optional-dependencies]
        non-prod = [
            { name = "sortedcontainers", version = "2.4.0", source = { registry = "http://[LOCALHOST]/simple/" } },
        ]
        prod = [
            { name = "sortedcontainers", version = "2.3.0", source = { registry = "http://[LOCALHOST]/simple/" } },
        ]

        [package.metadata]
        requires-dist = [
            { name = "sortedcontainers", marker = "extra == 'non-prod'", specifier = "==2.4.0" },
            { name = "sortedcontainers", marker = "extra == 'prod'", specifier = "==2.3.0" },
        ]
        provides-extras = ["prod", "non-prod"]

        [[package]]
        name = "sortedcontainers"
        version = "2.3.0"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/sortedcontainers-2.3.0.tar.gz", hash = "sha256:c7bfd220eb6dcc29774e2e05298edc2c5d62fa1086cc6409c800c7f413afe2a6", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/sortedcontainers-2.3.0-py3-none-any.whl", hash = "sha256:3228c480e84b2b7a504f28bd68f73b8cfde1d1fddf8a47783b19a0dbcc93ffcf", upload-time = "2024-03-24T00:00:00Z" },
        ]

        [[package]]
        name = "sortedcontainers"
        version = "2.4.0"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/sortedcontainers-2.4.0.tar.gz", hash = "sha256:fb6015d312cfaf15c65e0aeadac28191546cc25e48d41b126ecc322d5b116be2", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/sortedcontainers-2.4.0-py3-none-any.whl", hash = "sha256:e90c0f20bb5c630bbf840e4ccc94441cd55ae8048cf55fc42df715d28b67cb80", upload-time = "2024-03-24T00:00:00Z" },
        ]

        [[package]]
        name = "workspace-demo"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "package-a" },
        ]

        [package.optional-dependencies]
        non-prod = [
            { name = "package-a", extra = ["non-prod"], marker = "(extra == 'extra-14-workspace-demo-non-prod' and extra == 'extra-14-workspace-demo-prod') or (extra == 'extra-14-workspace-demo-non-prod' and extra == 'extra-9-package-a-non-prod') or (extra == 'extra-9-package-a-non-prod' and extra == 'extra-9-package-a-prod')" },
        ]
        prod = [
            { name = "package-a", extra = ["prod"], marker = "(extra == 'extra-14-workspace-demo-non-prod' and extra == 'extra-14-workspace-demo-prod') or (extra == 'extra-14-workspace-demo-prod' and extra == 'extra-9-package-a-prod') or (extra == 'extra-9-package-a-non-prod' and extra == 'extra-9-package-a-prod')" },
        ]

        [package.metadata]
        requires-dist = [
            { name = "package-a", editable = "packages/package-a" },
            { name = "package-a", extras = ["non-prod"], marker = "extra == 'non-prod'", editable = "packages/package-a" },
            { name = "package-a", extras = ["prod"], marker = "extra == 'prod'", editable = "packages/package-a" },
        ]
        provides-extras = ["prod", "non-prod"]
        "#
        );
    });

    context.lock().arg("--refresh").assert().success();
    assert_eq!(lock, context.read("uv.lock"));

    uv_snapshot!(context.filters(), context.lock().arg("--check").arg("--refresh"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    let lock = lock_without_package_metadata(&context.read("uv.lock"))?;
    context
        .temp_dir
        .child("uv.lock")
        .write_str(&lock.to_string())?;

    uv_snapshot!(context.filters(), context.lock()
        .arg("--preview-features")
        .arg("lock-without-metadata")
        .arg("--locked")
        .arg("--offline"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 4 packages in [TIME]
    ");

    Ok(())
}

/// Respect the locked version in an existing lockfile.
#[cfg(feature = "test-universal")]
#[test]
fn lock_preference() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["iniconfig<2"]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "iniconfig"
        version = "1.1.1"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/iniconfig-1.1.1.tar.gz", hash = "sha256:4f511134392ee75a8077a69be0d19cd4e5abb3a99ca54c7ab4a8e09ba0bc6991", upload-time = "2020-10-14T10:20:18.572Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/iniconfig-1.1.1-py3-none-any.whl", hash = "sha256:7832a237a8357e11d0a6e6a909bff9806c6f378393862998cd328fcf9d54d509", upload-time = "2020-10-14T10:20:18.572Z" },
        ]

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "iniconfig" },
        ]

        [package.metadata]
        requires-dist = [{ name = "iniconfig", specifier = "<2" }]
        "#
        );
    });

    // Modify the `pyproject.toml` to loosen the requirement.
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["iniconfig"]
        "#,
    )?;

    // Ensure that the locked version is still respected.
    //
    // Note that we do not use `deterministic!` here because the results depend on the existing lockfile.
    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "iniconfig"
        version = "1.1.1"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/iniconfig-1.1.1.tar.gz", hash = "sha256:4f511134392ee75a8077a69be0d19cd4e5abb3a99ca54c7ab4a8e09ba0bc6991", upload-time = "2020-10-14T10:20:18.572Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/iniconfig-1.1.1-py3-none-any.whl", hash = "sha256:7832a237a8357e11d0a6e6a909bff9806c6f378393862998cd328fcf9d54d509", upload-time = "2020-10-14T10:20:18.572Z" },
        ]

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "iniconfig" },
        ]

        [package.metadata]
        requires-dist = [{ name = "iniconfig" }]
        "#
        );
    });

    uv_snapshot!(context.filters(), context.lock().arg("--upgrade"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    Updated iniconfig v1.1.1 -> v2.0.0
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "iniconfig"
        version = "2.0.0"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/iniconfig-2.0.0.tar.gz", hash = "sha256:48c42a08c0ec1a24f2fe45f4efdefc9c19ac8e0aa8e82284503ccba80398bec3", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/iniconfig-2.0.0-py3-none-any.whl", hash = "sha256:8a0fc44e516906bdecc91af1c3bc12134c9d1647a482446edc62f2f72191416c", upload-time = "2024-03-24T00:00:00Z" },
        ]

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "iniconfig" },
        ]

        [package.metadata]
        requires-dist = [{ name = "iniconfig" }]
        "#
        );
    });

    Ok(())
}

/// If the user includes `git+` in a `tool.uv.sources` entry, we shouldn't fail.
#[cfg(all(feature = "test-universal", feature = "test-git"))]
#[test]
fn lock_git_plus_prefix() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["uv-public-pypackage"]

        [tool.uv.sources]
        uv-public-pypackage = { git = "git+https://github.com/astral-test/uv-public-pypackage" }
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "uv-public-pypackage" },
        ]

        [package.metadata]
        requires-dist = [{ name = "uv-public-pypackage", git = "https://github.com/astral-test/uv-public-pypackage" }]

        [[package]]
        name = "uv-public-pypackage"
        version = "0.1.0"
        source = { git = "https://github.com/astral-test/uv-public-pypackage#b270df1a2fb5d012294e9aaf05e7e0bab1e6a389" }
        "#
        );
    });

    // Re-run with `--locked`.
    uv_snapshot!(context.filters(), context.lock().arg("--locked"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    // Install from the lockfile, excluding development dependencies.
    uv_snapshot!(context.filters(), context.sync().arg("--frozen").arg("--no-dev"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Prepared 1 package in [TIME]
    Installed 1 package in [TIME]
     + uv-public-pypackage==0.1.0 (from git+https://github.com/astral-test/uv-public-pypackage@b270df1a2fb5d012294e9aaf05e7e0bab1e6a389)
    ");

    Ok(())
}

