/// Check relative and absolute path handling in lockfiles.
#[test]
fn lock_relative_and_absolute_paths() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(&formatdoc! {r#"
        [project]
        name = "a"
        version = "0.1.0"
        requires-python = ">=3.11,<3.13"
        dependencies = ["b", "c"]

        [tool.uv.sources]
        b = {{ path = "b" }}
        c = {{ path = '{}' }}
        "#,
        context.temp_dir.join("c").display()
    })?;
    context.temp_dir.child("a/__init__.py").touch()?;
    context
        .temp_dir
        .child("b/pyproject.toml")
        .write_str(indoc! {r#"
        [project]
        name = "b"
        version = "0.1.0"
        dependencies = []
        requires-python = ">=3.11,<3.13"
        license = {text = "MIT"}

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"

    "#})?;
    context.temp_dir.child("b/b/__init__.py").touch()?;
    context
        .temp_dir
        .child("c/pyproject.toml")
        .write_str(indoc! {r#"
        [project]
        name = "c"
        version = "0.1.0"
        dependencies = []
        requires-python = ">=3.11,<3.13"
        license = {text = "MIT"}

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
    "#})?;
    context.temp_dir.child("c/c/__init__.py").touch()?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 3 packages in [TIME]
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.11, <3.13"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "a"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "b" },
            { name = "c" },
        ]

        [package.metadata]
        requires-dist = [
            { name = "b", directory = "b" },
            { name = "c", directory = "[TEMP_DIR]/c" },
        ]

        [[package]]
        name = "b"
        version = "0.1.0"
        source = { directory = "b" }

        [[package]]
        name = "c"
        version = "0.1.0"
        source = { directory = "[TEMP_DIR]/c" }
        "#
        );
    });

    // Re-run with `--locked`.
    uv_snapshot!(context.filters(), context.lock().arg("--locked"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 3 packages in [TIME]
    ");

    Ok(())
}

/// Check path spelling for editable and non-editable sources in separate marker branches.
#[test]
fn lock_relative_and_absolute_paths_disjoint_markers() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let child = context.temp_dir.child("child");
    child.child("src/child/__init__.py").touch()?;
    child.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "child"
        version = "0.1.0"
        requires-python = ">=3.12"

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
    "#})?;

    context
        .temp_dir
        .child("pyproject.toml")
        .write_str(&formatdoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["child"]

        [tool.uv.sources]
        child = [
            {{ path = "child", editable = true, marker = "sys_platform == 'darwin'" }},
            {{ path = '{}', editable = false, marker = "sys_platform != 'darwin'" }},
        ]
    "#,
            child.path().display()
        })?;

    context.lock().assert().success();

    let lock = context.read("uv.lock");
    let sources = lock
        .lines()
        .filter(|line| line.contains("directory = ") || line.contains("editable = "))
        .collect::<Vec<_>>()
        .join("\n");

    // Each branch keeps its own path spelling in packages, dependencies, and metadata.
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(sources, @r#"
        source = { directory = "[TEMP_DIR]/child" }
        source = { editable = "child" }
            { name = "child", version = "0.1.0", source = { directory = "[TEMP_DIR]/child" }, marker = "sys_platform != 'darwin'" },
            { name = "child", version = "0.1.0", source = { editable = "child" }, marker = "sys_platform == 'darwin'" },
            { name = "child", marker = "sys_platform != 'darwin'", directory = "[TEMP_DIR]/child" },
            { name = "child", marker = "sys_platform == 'darwin'", editable = "child" },
        "#);
    });

    context.lock().arg("--check").assert().success();

    Ok(())
}

/// Poetry's generated URLs must not override authored relative or absolute source paths.
///
/// Note: Currently broken.
/// See: <https://github.com/astral-sh/uv/issues/20477>
#[test]
fn lock_relative_transitive_poetry_paths() -> Result<()> {
    let context = uv_test::test_context!("3.12").with_exclude_newer("2026-07-10T00:00:00Z");

    let absolute_child = context.temp_dir.child("absolute-child");
    let editable_child = context.temp_dir.child("editable-child");
    let project = context.temp_dir.child("project");
    project.child("pyproject.toml").write_str(&formatdoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["parent", "editable-child", "absolute-child"]

        [tool.uv.sources]
        parent = {{ path = "../parent", editable = true }}
        editable-child = {{ path = "../editable-child", editable = true }}
        absolute-child = {{ path = '{}' }}
    "#,
        absolute_child.path().display()
    })?;

    let parent = context.temp_dir.child("parent");
    parent.child("parent/__init__.py").touch()?;
    parent.child("pyproject.toml").write_str(indoc! {r#"
        [tool.poetry]
        name = "parent"
        version = "0.1.0"
        description = ""
        packages = [{ include = "parent" }]

        [tool.poetry.dependencies]
        python = ">=3.12,<3.13"

        [build-system]
        requires = ["poetry-core"]
        build-backend = "poetry.core.masonry.api"
    "#})?;

    absolute_child.child("absolute_child/__init__.py").touch()?;
    absolute_child
        .child("pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "absolute-child"
            version = "0.1.0"
            requires-python = ">=3.12"

            [build-system]
            requires = ["hatchling"]
            build-backend = "hatchling.build"
        "#})?;

    editable_child.child("editable_child/__init__.py").touch()?;
    editable_child
        .child("pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "editable-child"
            version = "0.1.0"
            requires-python = ">=3.12"

            [build-system]
            requires = ["hatchling"]
            build-backend = "hatchling.build"
        "#})?;

    context
        .lock()
        .current_dir(project.path())
        .assert()
        .success();

    let lock = context.read("project/uv.lock");

    parent.child("pyproject.toml").write_str(indoc! {r#"
        [tool.poetry]
        name = "parent"
        version = "0.1.0"
        description = ""
        packages = [{ include = "parent" }]

        [tool.poetry.dependencies]
        python = ">=3.12,<3.13"
        editable-child = { path = "../editable-child", develop = true }
        absolute-child = { path = "../absolute-child" }

        [build-system]
        requires = ["poetry-core"]
        build-backend = "poetry.core.masonry.api"
    "#})?;

    context
        .lock()
        .current_dir(project.path())
        .assert()
        .success();

    // The root's sources must stay unchanged; Poetry's requirement paths should be relative.
    let new_lock = context.read("project/uv.lock");
    let diff = diff_snapshot(&lock, &new_lock, 3);
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(diff, @r#"
        --- old
        +++ new
        @@ -13,12 +13,22 @@
         [[package]]
         name = "editable-child"
         version = "0.1.0"
        -source = { editable = "../editable-child" }
        +source = { editable = "[TEMP_DIR]/editable-child" }

         [[package]]
         name = "parent"
         version = "0.1.0"
         source = { editable = "../parent" }
        +dependencies = [
        +    { name = "absolute-child" },
        +    { name = "editable-child" },
        +]
        +
        +[package.metadata]
        +requires-dist = [
        +    { name = "absolute-child", directory = "[TEMP_DIR]/absolute-child" },
        +    { name = "editable-child", directory = "[TEMP_DIR]/editable-child" },
        +]

         [[package]]
         name = "project"
        "#);
    });

    // Cached Poetry metadata must preserve the same paths when the lockfile is recreated.
    fs_err::remove_file(project.child("uv.lock").path())?;
    context
        .lock()
        .current_dir(project.path())
        .assert()
        .success();
    assert_eq!(new_lock, context.read("project/uv.lock"));

    project.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["parent"]

        [tool.uv.sources]
        parent = { path = "../parent", editable = true }
    "#})?;

    context
        .lock()
        .current_dir(project.path())
        .assert()
        .success();

    // Without direct sources, both children should use relative, non-editable paths.
    let backend_only_lock = context.read("project/uv.lock");
    let diff = diff_snapshot(&new_lock, &backend_only_lock, 3);
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(diff, @r#"
        --- old
        +++ new
        @@ -13,7 +13,7 @@
         [[package]]
         name = "editable-child"
         version = "0.1.0"
        -source = { editable = "[TEMP_DIR]/editable-child" }
        +source = { directory = "[TEMP_DIR]/editable-child" }

         [[package]]
         name = "parent"
        @@ -35,14 +35,8 @@
         version = "0.1.0"
         source = { virtual = "." }
         dependencies = [
        -    { name = "absolute-child" },
        -    { name = "editable-child" },
             { name = "parent" },
         ]

         [package.metadata]
        -requires-dist = [
        -    { name = "absolute-child", directory = "[TEMP_DIR]/absolute-child" },
        -    { name = "editable-child", editable = "../editable-child" },
        -    { name = "parent", editable = "../parent" },
        -]
        +requires-dist = [{ name = "parent", editable = "../parent" }]
        "#);
    });

    Ok(())
}

/// Check workspace paths when a dependency reports an equivalent absolute file URL.
///
/// Note: Currently broken.
/// See: <https://github.com/astral-sh/uv/issues/20477>
#[test]
fn lock_relative_transitive_workspace_paths() -> Result<()> {
    let context = uv_test::test_context!("3.12").with_exclude_newer("2026-07-10T00:00:00Z");

    context
        .temp_dir
        .child("pyproject.toml")
        .write_str(indoc! {r#"
        [tool.uv.workspace]
        members = ["member"]

        [tool.uv.sources]
        intermediate = { path = "intermediate", editable = true }
        shared-dependency = { path = "shared-dependency" }
    "#})?;

    let member = context.temp_dir.child("member");
    member.child("member/__init__.py").touch()?;
    member.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "member"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["intermediate", "shared-dependency"]

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    let shared_dependency = context.temp_dir.child("shared-dependency");

    let intermediate = context.temp_dir.child("intermediate");
    intermediate.child("intermediate/__init__.py").touch()?;
    intermediate.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "intermediate"
        version = "0.1.0"
        requires-python = ">=3.12"

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    shared_dependency
        .child("shared_dependency/__init__.py")
        .touch()?;
    shared_dependency
        .child("pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "shared-dependency"
            version = "0.1.0"

            [build-system]
            requires = ["hatchling"]
            build-backend = "hatchling.build"
        "#})?;

    context.lock().assert().success();

    let lock = context.read("uv.lock");

    let shared_dependency_alias = context.temp_dir.child("shared-dependency-alias");
    create_symlink(shared_dependency.path(), shared_dependency_alias.path())?;
    let shared_dependency_url = Url::from_file_path(shared_dependency_alias.path())
        .map_err(|()| anyhow::anyhow!("shared dependency path is not a valid file URL"))?;

    intermediate
        .child("pyproject.toml")
        .write_str(&formatdoc! {r#"
        [project]
        name = "intermediate"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["shared-dependency @ {shared_dependency_url}"]

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    context.lock().assert().success();

    // Keep the workspace path and the intermediate's metadata alias relative to the lockfile.
    let new_lock = context.read("uv.lock");
    let diff = diff_snapshot(&lock, &new_lock, 3);
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(diff, @r#"
        --- old
        +++ new
        @@ -14,6 +14,12 @@
         name = "intermediate"
         version = "0.1.0"
         source = { editable = "intermediate" }
        +dependencies = [
        +    { name = "shared-dependency" },
        +]
        +
        +[package.metadata]
        +requires-dist = [{ name = "shared-dependency", directory = "[TEMP_DIR]/shared-dependency-alias" }]

         [[package]]
         name = "member"
        @@ -33,4 +39,4 @@
         [[package]]
         name = "shared-dependency"
         version = "0.1.0"
        -source = { directory = "shared-dependency" }
        +source = { directory = "[TEMP_DIR]/shared-dependency-alias" }
        "#);
    });

    // The recorded alias must still match the intermediate's unchanged metadata.
    context
        .lock()
        .arg("--check")
        .arg("--offline")
        .arg("--no-cache")
        .assert()
        .success();

    Ok(())
}

/// Check local archive paths when a dependency reports equivalent absolute file URLs.
///
/// Note: Currently broken.
/// See: <https://github.com/astral-sh/uv/issues/20477>
#[test]
fn lock_relative_transitive_archive_paths() -> Result<()> {
    let context = uv_test::test_context!("3.13").with_exclude_newer("2026-07-10T00:00:00Z");

    let wheel = context.temp_dir.child("wheels/ok-1.0.0-py3-none-any.whl");
    context.temp_dir.child("wheels").create_dir_all()?;
    fs_err::copy(
        context
            .workspace_root
            .join("test/links/ok-1.0.0-py3-none-any.whl"),
        wheel.path(),
    )?;
    let wheel_url = Url::from_file_path(wheel.path())
        .map_err(|()| anyhow::anyhow!("wheel path is not a valid file URL"))?;

    let source_archive = context
        .temp_dir
        .child("archives/basic_package-0.1.0.tar.gz");
    context.temp_dir.child("archives").create_dir_all()?;
    fs_err::copy(
        context
            .workspace_root
            .join("test/links/basic_package-0.1.0.tar.gz"),
        source_archive.path(),
    )?;
    let source_archive_url = Url::from_file_path(source_archive.path())
        .map_err(|()| anyhow::anyhow!("source archive path is not a valid file URL"))?;

    let project = context.temp_dir.child("project");
    project.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.13"
        dependencies = ["parent", "ok", "basic-package"]

        [tool.uv.sources]
        parent = { path = "../parent", editable = true }
        ok = { path = "../wheels/ok-1.0.0-py3-none-any.whl" }
        basic-package = { path = "../archives/basic_package-0.1.0.tar.gz" }
    "#})?;

    let parent = context.temp_dir.child("parent");
    parent.child("parent/__init__.py").touch()?;
    parent.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "parent"
        version = "0.1.0"
        requires-python = ">=3.13"

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    context
        .lock()
        .current_dir(project.path())
        .assert()
        .success();

    let lock = context.read("project/uv.lock");

    parent.child("pyproject.toml").write_str(&formatdoc! {r#"
        [project]
        name = "parent"
        version = "0.1.0"
        requires-python = ">=3.13"
        dependencies = [
            "ok @ {wheel_url}",
            "basic-package @ {source_archive_url}",
        ]

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    context
        .lock()
        .current_dir(project.path())
        .assert()
        .success();

    // Root-selected wheel and sdist paths must stay relative in packages and metadata.
    let new_lock = context.read("project/uv.lock");
    let diff = diff_snapshot(&lock, &new_lock, 3);
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(diff, @r#"
        --- old
        +++ new
        @@ -8,13 +8,13 @@
         [[package]]
         name = "basic-package"
         version = "0.1.0"
        -source = { path = "../archives/basic_package-0.1.0.tar.gz" }
        +source = { path = "[TEMP_DIR]/archives/basic_package-0.1.0.tar.gz" }
         sdist = { hash = "sha256:af478ff91ec60856c99a540b8df13d756513bebb65bc301fb27e0d1f974532b4" }

         [[package]]
         name = "ok"
         version = "1.0.0"
        -source = { path = "../wheels/ok-1.0.0-py3-none-any.whl" }
        +source = { path = "[TEMP_DIR]/wheels/ok-1.0.0-py3-none-any.whl" }
         wheels = [
             { filename = "ok-1.0.0-py3-none-any.whl", hash = "sha256:79f0b33e6ce1e09eaa1784c8eee275dfe84d215d9c65c652f07c18e85fdaac5f" },
         ]
        @@ -23,6 +23,16 @@
         name = "parent"
         version = "0.1.0"
         source = { editable = "../parent" }
        +dependencies = [
        +    { name = "basic-package" },
        +    { name = "ok" },
        +]
        +
        +[package.metadata]
        +requires-dist = [
        +    { name = "basic-package", path = "[TEMP_DIR]/archives/basic_package-0.1.0.tar.gz" },
        +    { name = "ok", path = "[TEMP_DIR]/wheels/ok-1.0.0-py3-none-any.whl" },
        +]

         [[package]]
         name = "project"
        "#);
    });

    project.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.13"
        dependencies = ["parent"]

        [tool.uv.sources]
        parent = { path = "../parent", editable = true }
    "#})?;

    context
        .lock()
        .current_dir(project.path())
        .assert()
        .success();

    let backend_only_lock = context.read("project/uv.lock");
    let archive_paths = backend_only_lock
        .lines()
        .filter(|line| line.contains("path = "))
        .collect::<Vec<_>>()
        .join("\n");

    // Metadata-only wheel and sdist paths must be relative in packages and requirements.
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(archive_paths, @r#"
        source = { path = "[TEMP_DIR]/archives/basic_package-0.1.0.tar.gz" }
        source = { path = "[TEMP_DIR]/wheels/ok-1.0.0-py3-none-any.whl" }
            { name = "basic-package", path = "[TEMP_DIR]/archives/basic_package-0.1.0.tar.gz" },
            { name = "ok", path = "[TEMP_DIR]/wheels/ok-1.0.0-py3-none-any.whl" },
        "#);
    });

    Ok(())
}

/// Preserve local path intent across configured, workspace, and backend metadata.
///
/// Note: Currently broken: backend paths stay absolute and override the configured source.
#[test]
fn lock_relative_inactive_dependency_metadata_paths() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let child = context.temp_dir.child("child");
    child.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "child"
        version = "0.1.0"
        requires-python = ">=3.12"
    "#})?;
    let child_url = Url::from_file_path(child.path())
        .map_err(|()| anyhow::anyhow!("child path is not a valid file URL"))?;

    let active_child = context.temp_dir.child("active-child");
    active_child.child("active_child/__init__.py").touch()?;
    active_child.child("pyproject.toml").write_str(indoc! {r#"
            [project]
            name = "active-child"
            version = "0.1.0"
            requires-python = ">=3.12"

            [build-system]
            requires = ["hatchling"]
            build-backend = "hatchling.build"
        "#})?;
    let active_child_url = Url::from_file_path(active_child.path())
        .map_err(|()| anyhow::anyhow!("active child path is not a valid file URL"))?;

    let relative_child = context.temp_dir.child("relative-child");
    relative_child.child("relative_child/__init__.py").touch()?;
    relative_child
        .child("pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "relative-child"
            version = "0.1.0"
            requires-python = ">=3.12"

            [build-system]
            requires = ["hatchling"]
            build-backend = "hatchling.build"
        "#})?;
    let relative_child_url = Url::from_file_path(relative_child.path())
        .map_err(|()| anyhow::anyhow!("relative child path is not a valid file URL"))?;
    let relative_child_alias = context.temp_dir.child("relative-child-alias");
    create_symlink(relative_child.path(), relative_child_alias.path())?;
    let relative_child_alias_url = Url::from_file_path(relative_child_alias.path())
        .map_err(|()| anyhow::anyhow!("relative child alias is not a valid file URL"))?;

    // Discover the ordinary parent through configured metadata to keep the baseline deterministic.
    let parent = context.temp_dir.child("parent");
    let parent_url = Url::from_file_path(parent.path())
        .map_err(|()| anyhow::anyhow!("parent path is not a valid file URL"))?;

    let project = indoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = [
            "authored-parent",
            "member",
        ]

        [tool.uv.workspace]
        members = ["member"]

        [tool.uv.sources]
        authored-parent = { path = "authored-parent" }
        member = { workspace = true }

        [[tool.uv.dependency-metadata]]
        name = "authored-parent"
        version = "0.1.0"
    "#};
    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(&formatdoc! {r"
        {project}
        requires-dist = []
    "})?;

    context
        .temp_dir
        .child("authored-parent/pyproject.toml")
        .write_str(indoc! {r#"
            [project]
            name = "authored-parent"
            version = "0.1.0"
            requires-python = ">=3.12"
            dynamic = ["dependencies"]
        "#})?;

    let member = context.temp_dir.child("member");
    member.child("member/__init__.py").touch()?;
    member.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "member"
        version = "0.1.0"
        requires-python = ">=3.12"

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    parent.child("parent/__init__.py").touch()?;
    parent.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "parent"
        version = "0.1.0"
        requires-python = ">=3.12"

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    context.lock().assert().success();

    let baseline_lock = context.read("uv.lock");

    pyproject_toml.write_str(&formatdoc! {r#"
        {project}
        requires-dist = [
            "active-child @ {active_child_url}",
            "child @ {child_url}; python_version < '0'",
            "parent @ {parent_url}",
            "relative-child @ ${{UV_TEST_CONFIGURED_CHILD_URL}}",
        ]
    "#})?;

    member.child("pyproject.toml").write_str(&formatdoc! {r#"
        [project]
        name = "member"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["child @ {child_url}; python_version < '0'"]

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    context
        .lock()
        .env("UV_TEST_CONFIGURED_CHILD_URL", relative_child_url.as_str())
        .assert()
        .success();

    let lock = context.read("uv.lock");
    let diff = diff_snapshot(&baseline_lock, &lock, 3);

    // Explicit absolute inputs, including inactive requirements, must stay absolute.
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(diff, @r#"
        --- old
        +++ new
        @@ -14,17 +14,44 @@
         [[manifest.dependency-metadata]]
         name = "authored-parent"
         version = "0.1.0"
        +requires-dist = ["active-child @ file://[TEMP_DIR]/active-child", "child @ file://[TEMP_DIR]/child ; python_full_version < '0'", "parent @ file://[TEMP_DIR]/parent", "relative-child @ file://[TEMP_DIR]/relative-child"]
        +
        +[[package]]
        +name = "active-child"
        +version = "0.1.0"
        +source = { directory = "[TEMP_DIR]/active-child" }

         [[package]]
         name = "authored-parent"
         version = "0.1.0"
         source = { directory = "authored-parent" }
        +dependencies = [
        +    { name = "active-child" },
        +    { name = "parent" },
        +    { name = "relative-child" },
        +]
        +
        +[package.metadata]
        +requires-dist = [
        +    { name = "active-child", directory = "[TEMP_DIR]/active-child" },
        +    { name = "child", marker = "python_full_version < '0'", directory = "[TEMP_DIR]/child" },
        +    { name = "parent", directory = "[TEMP_DIR]/parent" },
        +    { name = "relative-child", directory = "relative-child" },
        +]

         [[package]]
         name = "member"
         version = "0.1.0"
         source = { editable = "member" }

        +[package.metadata]
        +requires-dist = [{ name = "child", marker = "python_full_version < '0'", directory = "[TEMP_DIR]/child" }]
        +
        +[[package]]
        +name = "parent"
        +version = "0.1.0"
        +source = { directory = "[TEMP_DIR]/parent" }
        +
         [[package]]
         name = "project"
         version = "0.1.0"
        @@ -39,3 +66,8 @@
             { name = "authored-parent", directory = "authored-parent" },
             { name = "member", editable = "member" },
         ]
        +
        +[[package]]
        +name = "relative-child"
        +version = "0.1.0"
        +source = { directory = "relative-child" }
        "#);
    });

    parent.child("pyproject.toml").write_str(&formatdoc! {r#"
        [project]
        name = "parent"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["relative-child @ {relative_child_alias_url}"]

        [project.optional-dependencies]
        unused = ["child @ {child_url}"]

        [build-system]
        requires = ["hatchling"]
        build-backend = "hatchling.build"
    "#})?;

    context
        .lock()
        .env("UV_TEST_CONFIGURED_CHILD_URL", relative_child_url.as_str())
        .assert()
        .success();

    let new_lock = context.read("uv.lock");
    let diff = diff_snapshot(&lock, &new_lock, 3);

    // Keep the configured `relative-child` source unchanged. Backend requirements should use
    // `relative-child-alias` and `child`, both relative to the lockfile.
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(diff, @r#"
        --- old
        +++ new
        @@ -51,6 +51,16 @@
         name = "parent"
         version = "0.1.0"
         source = { directory = "[TEMP_DIR]/parent" }
        +dependencies = [
        +    { name = "relative-child" },
        +]
        +
        +[package.metadata]
        +requires-dist = [
        +    { name = "child", marker = "extra == 'unused'", directory = "[TEMP_DIR]/child" },
        +    { name = "relative-child", directory = "[TEMP_DIR]/relative-child-alias" },
        +]
        +provides-extras = ["unused"]

         [[package]]
         name = "project"
        @@ -70,4 +80,4 @@
         [[package]]
         name = "relative-child"
         version = "0.1.0"
        -source = { directory = "relative-child" }
        +source = { directory = "[TEMP_DIR]/relative-child-alias" }
        "#);
    });

    Ok(())
}

/// Ignored metadata overrides must not make backend paths appear user-authored.
///
/// Note: Currently broken: backend paths stay absolute when configured metadata is ignored.
#[test]
fn lock_ignored_dependency_metadata_paths() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let active_child = context.temp_dir.child("active-child");
    active_child.child("src/active_child/__init__.py").touch()?;
    active_child.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "active-child"
        version = "0.1.0"
        requires-python = ">=3.12"

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
    "#})?;
    let inactive_child = context.temp_dir.child("inactive-child");
    inactive_child
        .child("pyproject.toml")
        .write_str(indoc! {r#"
        [project]
        name = "inactive-child"
        version = "0.1.0"
        requires-python = ">=3.12"
    "#})?;
    let active_child_url = Url::from_file_path(active_child.path())
        .map_err(|()| anyhow::anyhow!("active child path is not a valid file URL"))?;
    let inactive_child_url = Url::from_file_path(inactive_child.path())
        .map_err(|()| anyhow::anyhow!("inactive child path is not a valid file URL"))?;

    let parent = context.temp_dir.child("parent");
    parent.child("src/parent/__init__.py").touch()?;
    parent.child("pyproject.toml").write_str(&formatdoc! {r#"
        [project]
        name = "parent"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = [
            "active-child @ {active_child_url}",
            "inactive-child @ {inactive_child_url}; python_version < '0'",
        ]

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
    "#})?;

    let project = indoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["parent"]

        [tool.uv.sources]
        parent = { path = "parent" }
    "#};
    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(&formatdoc! {r#"
        {project}

        [[tool.uv.dependency-metadata]]
        name = "parent"
        requires-dist = []
    "#})?;

    let child_paths = |lock: &str| {
        lock.lines()
            .filter(|line| line.contains("directory = ") && line.contains("child"))
            .collect::<Vec<_>>()
            .join("\n")
    };

    context.lock().assert().success();
    let paths = child_paths(&context.read("uv.lock"));

    // Active and inactive backend paths stay relative when metadata overrides are ignored.
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(paths, @r#"
        source = { directory = "[TEMP_DIR]/active-child" }
            { name = "active-child", directory = "[TEMP_DIR]/active-child" },
            { name = "inactive-child", marker = "python_full_version < '0'", directory = "[TEMP_DIR]/inactive-child" },
        "#);
    });

    // Multiple entries are also unusable before the directory's version is known.
    pyproject_toml.write_str(&formatdoc! {r#"
        {project}

        [[tool.uv.dependency-metadata]]
        name = "parent"
        version = "0.1.0"
        requires-dist = []

        [[tool.uv.dependency-metadata]]
        name = "parent"
        version = "0.2.0"
        requires-dist = []
    "#})?;
    fs_err::remove_file(context.temp_dir.child("uv.lock").path())?;
    context.lock().assert().success();
    assert_eq!(paths, child_paths(&context.read("uv.lock")));

    Ok(())
}

/// Check PEP 508 URL handling when they contain variables
#[cfg(feature = "test-universal")]
#[test]
fn lock_pep508_urls_with_vars() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(&indoc! {r#"
        [project]
        name = "a"
        version = "0.1.0"
        requires-python = ">=3.11,<3.13"
        dependencies = ["b @ file://${PWD}/b", "c @ file:///${PROJECT_ROOT}/c"]
        "#,
    })?;
    context.temp_dir.child("src/a/__init__.py").touch()?;
    context
        .temp_dir
        .child("b/pyproject.toml")
        .write_str(indoc! {r#"
        [project]
        name = "b"
        version = "0.1.0"
        dependencies = []
        requires-python = ">=3.11,<3.13"
        license = {text = "MIT"}

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"

    "#})?;
    context.temp_dir.child("src/b/__init__.py").touch()?;
    context
        .temp_dir
        .child("c/pyproject.toml")
        .write_str(indoc! {r#"
        [project]
        name = "c"
        version = "0.1.0"
        dependencies = []
        requires-python = ">=3.11,<3.13"
        license = {text = "MIT"}

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
    "#})?;
    context.temp_dir.child("src/c/__init__.py").touch()?;

    uv_snapshot!(context.filters(), context.lock().env("PWD", context.temp_dir.path()), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 3 packages in [TIME]
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.11, <3.13"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "a"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "b" },
            { name = "c" },
        ]

        [package.metadata]
        requires-dist = [
            { name = "b", directory = "b" },
            { name = "c", directory = "c" },
        ]

        [[package]]
        name = "b"
        version = "0.1.0"
        source = { directory = "b" }

        [[package]]
        name = "c"
        version = "0.1.0"
        source = { directory = "c" }
        "#
        );
    });

    // Re-run with `--locked`.
    uv_snapshot!(context.filters(), context.lock().env("PWD", context.temp_dir.path()).arg("--locked"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 3 packages in [TIME]
    ");

    Ok(())
}

/// Check relative and absolute path handling in constraint-dependencies.
///
/// When a user provides an absolute path in `constraint-dependencies`, it should be preserved
/// as absolute in the lockfile manifest.
///
/// See: <https://github.com/astral-sh/uv/issues/17307>
#[test]
fn lock_constraint_dependency_absolute_path() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    // Create a local sniffio package at an absolute path.
    // We use sniffio because anyio depends on it, so the constraint will
    // actually be used in the resolution and its path will appear in the
    // lockfile package list.
    let sniffio_pkg = context.temp_dir.child("sniffio_local");
    sniffio_pkg.child("pyproject.toml").write_str(indoc! {r#"
        [project]
        name = "sniffio"
        version = "1.3.1"
        requires-python = ">=3.12"
        dependencies = []

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
    "#})?;
    sniffio_pkg
        .child("src")
        .child("sniffio")
        .child("__init__.py")
        .touch()?;

    // Create the main project with a constraint-dependency using an absolute path.
    let pyproject_toml = context.temp_dir.child("project").child("pyproject.toml");
    pyproject_toml.write_str(&formatdoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio==3.7.0"]

        [tool.uv]
        constraint-dependencies = ["sniffio @ {}"]
        "#,
        sniffio_pkg.portable_display()
    })?;

    uv_snapshot!(context.filters(), context.lock().current_dir(context.temp_dir.join("project")), @"
    exit_code: 0 (success)
    ----- stderr -----
    Using CPython 3.12.[X] interpreter at: [PYTHON-3.12]
    Resolved 4 packages in [TIME]
    ");

    // Check the lockfile - the absolute path should stay absolute, and sniffio
    // should be resolved from the local path rather than PyPI.
    let lock = fs_err::read_to_string(context.temp_dir.join("project/uv.lock"))?;

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [manifest]
        constraints = [{ name = "sniffio", directory = "[TEMP_DIR]/sniffio_local" }]

        [[package]]
        name = "anyio"
        version = "3.7.0"
        source = { registry = "http://[LOCALHOST]/simple/" }
        dependencies = [
            { name = "idna" },
            { name = "sniffio" },
        ]
        sdist = { url = "http://[LOCALHOST]/files/anyio-3.7.0.tar.gz", hash = "sha256:c8f99c47f03aec932b6cee4178beb10ce5b0aaf6d3e1ff52cc5e49fc3186af0a", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/anyio-3.7.0-py3-none-any.whl", hash = "sha256:ea75fecadcfa9b11a8bfa2ff25ea52a2904950d4925ba758c97d97e32c314556", upload-time = "2024-03-24T00:00:00Z" },
        ]

        [[package]]
        name = "idna"
        version = "3.6"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/idna-3.6.tar.gz", hash = "sha256:9aae8f72192b28db0d56fcef130afe490d1538a8d1bf1700e6d219521421525f", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/idna-3.6-py3-none-any.whl", hash = "sha256:e80025850eafa8760055fd6f2f6e83f84bf13d4a844fe81abb2b499e3a3e8af0", upload-time = "2024-03-24T00:00:00Z" },
        ]

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "anyio" },
        ]

        [package.metadata]
        requires-dist = [{ name = "anyio", specifier = "==3.7.0" }]

        [[package]]
        name = "sniffio"
        version = "1.3.1"
        source = { directory = "[TEMP_DIR]/sniffio_local" }
        "#
        );
    });

    Ok(())
}

/// Check that absolute index paths in config files are preserved in lockfiles.
///
/// When an index is specified with an absolute path in a config file (pyproject.toml),
/// that absolute path should be preserved in the lockfile.
///
/// See: <https://github.com/astral-sh/uv/issues/17307>
#[test]
fn lock_index_absolute_path_from_config() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    // Create a local flat index with a wheel.
    let index_dir = context.temp_dir.child("local_index");
    fs_err::create_dir_all(&index_dir)?;

    for entry in fs_err::read_dir(context.workspace_root.join("test/links"))? {
        let entry = entry?;
        let path = entry.path();
        if path
            .file_name()
            .and_then(|file_name| file_name.to_str())
            .is_some_and(|file_name| file_name.starts_with("tqdm-1000"))
        {
            let dest = index_dir.join(path.file_name().unwrap());
            fs_err::copy(&path, &dest)?;
        }
    }

    // Create a project directory.
    let project = context.temp_dir.child("project");
    fs_err::create_dir_all(&project)?;

    // Configure the index with an ABSOLUTE path in pyproject.toml.
    let pyproject_toml = project.child("pyproject.toml");
    pyproject_toml.write_str(&formatdoc! {r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["tqdm==1000.0.0"]

        [[tool.uv.index]]
        name = "local"
        url = "{}"
        format = "flat"
        "#,
        index_dir.portable_display()
    })?;

    uv_snapshot!(context.filters(), context.lock().current_dir(&project), @"
    exit_code: 0 (success)
    ----- stderr -----
    Using CPython 3.12.[X] interpreter at: [PYTHON-3.12]
    Resolved 2 packages in [TIME]
    ");

    // Check the lockfile - the absolute path should stay absolute.
    let lock = fs_err::read_to_string(project.join("uv.lock"))?;

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "tqdm" },
        ]

        [package.metadata]
        requires-dist = [{ name = "tqdm", specifier = "==1000.0.0" }]

        [[package]]
        name = "tqdm"
        version = "1000.0.0"
        source = { registry = "[TEMP_DIR]/local_index" }
        wheels = [
            { path = "[TEMP_DIR]/local_index/tqdm-1000.0.0-py3-none-any.whl" },
        ]
        "#
        );
    });

    Ok(())
}

