/// Regression test for <https://github.com/astral-sh/uv/issues/19916>.
///
/// Lock a workspace with a member that also supports standalone installation via platform-specific
/// path sources.
#[cfg(feature = "test-universal")]
#[test]
fn lock_workspace_member_with_standalone_path_source() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [tool.uv.workspace]
        members = ["root/app", "root/lib"]

        [tool.uv.sources]
        lib = { workspace = true }
        "#,
    )?;

    let root = context.temp_dir.child("root");
    root.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "root"
        version = "0.1.0"

        [tool.uv.sources]
        lib = { path = "lib" }
        "#,
    )?;

    root.child("app").child("pyproject.toml").write_str(
        r#"
        [project]
        name = "app"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["lib"]

        [tool.uv.sources]
        lib = [
            { path = "../lib", editable = true, marker = "sys_platform == 'darwin'" },
            { path = "../lib", editable = true, marker = "sys_platform != 'darwin'" },
        ]
        "#,
    )?;

    root.child("lib").child("pyproject.toml").write_str(
        r#"
        [project]
        name = "lib"
        version = "0.1.0"
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"
        resolution-markers = [
            "sys_platform == 'darwin'",
            "sys_platform != 'darwin'",
        ]

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [manifest]
        members = [
            "app",
            "lib",
        ]

        [[package]]
        name = "app"
        version = "0.1.0"
        source = { virtual = "root/app" }
        dependencies = [
            { name = "lib" },
        ]

        [package.metadata]
        requires-dist = [
            { name = "lib", marker = "sys_platform != 'darwin'", editable = "root/lib" },
            { name = "lib", marker = "sys_platform == 'darwin'", editable = "root/lib" },
        ]

        [[package]]
        name = "lib"
        version = "0.1.0"
        source = { editable = "root/lib" }
        "#
        );
    });

    Ok(())
}

/// Lock a project that correctly points at an external workspace via `workspace = "..."`.
#[cfg(feature = "test-universal")]
#[test]
fn lock_external_workspace_source() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let project = context.temp_dir.child("project");
    project.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["pkg-b"]

        [tool.uv.sources]
        pkg-b = { workspace = "../external-workspace" }
        "#,
    )?;

    let external_workspace = context.temp_dir.child("external-workspace");
    external_workspace.child("pyproject.toml").write_str(
        r#"
        [tool.uv.workspace]
        members = ["packages/*"]
        "#,
    )?;

    let external_member = external_workspace.child("packages").child("pkg-b");
    fs_err::create_dir_all(&external_member)?;
    external_member.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "pkg-b"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = []
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock().current_dir(&project), @"
    exit_code: 0 (success)
    ----- stderr -----
    Using CPython 3.12.[X] interpreter at: [PYTHON-3.12]
    Resolved 2 packages in [TIME]
    ");

    let lock = fs_err::read_to_string(project.join("uv.lock"))?;

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "pkg-b"
        version = "0.1.0"
        source = { editable = "../external-workspace/packages/pkg-b" }

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "pkg-b" },
        ]

        [package.metadata]
        requires-dist = [{ name = "pkg-b", editable = "../external-workspace/packages/pkg-b" }]
        "#
        );
    });

    // A workspace source must point to the workspace root, not one of its members.
    project.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["pkg-b"]

        [tool.uv.sources]
        pkg-b = { workspace = "../external-workspace/packages/pkg-b" }
        "#,
    )?;

    fs_err::remove_file(project.join("uv.lock"))?;

    uv_snapshot!(context.filters(), context.lock().current_dir(&project), @"
    exit_code: 1 (failure)
    ----- stderr -----
    Using CPython 3.12.[X] interpreter at: [PYTHON-3.12]
    error: Failed to build `project @ file://[TEMP_DIR]/project`
      cause: Failed to parse entry: `pkg-b`
      cause: Workspace source path `[TEMP_DIR]/external-workspace/packages/pkg-b` must point to a workspace root (found workspace at `[TEMP_DIR]/external-workspace`)
    ");

    Ok(())
}

