/// Lock a non-project workspace root with conflicts declared between members.
#[cfg(feature = "test-universal")]
#[test]
fn lock_non_project_member_conflicts() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [tool.uv.workspace]
        members = ["member-a", "member-b"]
        "#,
    )?;

    let member_a = context.temp_dir.child("member-a");
    member_a.create_dir_all()?;
    member_a.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "member-a"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["sortedcontainers==2.3.0"]

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    let member_b = context.temp_dir.child("member-b");
    member_b.create_dir_all()?;
    member_b.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "member-b"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["sortedcontainers==2.4.0"]

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 1 (failure)
    ----- stderr -----
    error: No solution found when resolving dependencies
      cause: Because member-a depends on sortedcontainers==2.3.0 and member-b depends on sortedcontainers==2.4.0, we can conclude that member-a and member-b are incompatible.
             And because your workspace requires member-a and member-b, we can conclude that your workspace's requirements are unsatisfiable.
    ");

    pyproject_toml.write_str(
        r#"
        [tool.uv.workspace]
        members = ["member-a", "member-b"]

        [tool.uv]
        conflicts = [
          [
            { package = "member-a" },
            { package = "member-b" },
          ],
        ]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    warning: Declaring conflicts for packages (`package = ...`) is experimental and may change without warning. Pass `--preview-features package-conflicts` to disable this warning.
    Resolved 4 packages in [TIME]
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"
        conflicts = [[
            { package = "member-a" },
            { package = "member-b" },
        ]]

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [manifest]
        members = [
            "member-a",
            "member-b",
        ]

        [[package]]
        name = "member-a"
        version = "0.1.0"
        source = { editable = "member-a" }
        dependencies = [
            { name = "sortedcontainers", version = "2.3.0", source = { registry = "http://[LOCALHOST]/simple/" }, marker = "extra == 'project-8-member-a'" },
        ]

        [package.metadata]
        requires-dist = [{ name = "sortedcontainers", specifier = "==2.3.0" }]

        [[package]]
        name = "member-b"
        version = "0.1.0"
        source = { editable = "member-b" }
        dependencies = [
            { name = "sortedcontainers", version = "2.4.0", source = { registry = "http://[LOCALHOST]/simple/" }, marker = "extra == 'project-8-member-b'" },
        ]

        [package.metadata]
        requires-dist = [{ name = "sortedcontainers", specifier = "==2.4.0" }]

        [[package]]
        name = "sortedcontainers"
        version = "2.3.0"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/sortedcontainers-2.3.0.tar.gz", hash = "sha256:c7bfd220eb6dcc29774e2e05298edc2c5d62fa1086cc6409c800c7f413afe2a6", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/sortedcontainers-2.3.0-py3-none-any.whl", hash = "sha256:3228c480e84b2b7a504f28bd68f73b8cfde1d1fddf8a47783b19a0dbcc93ffcf", upload-time = "2024-03-24T00:00:00Z" },
        ]

        [[package]]
        name = "sortedcontainers"
        version = "2.4.0"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/sortedcontainers-2.4.0.tar.gz", hash = "sha256:fb6015d312cfaf15c65e0aeadac28191546cc25e48d41b126ecc322d5b116be2", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/sortedcontainers-2.4.0-py3-none-any.whl", hash = "sha256:e90c0f20bb5c630bbf840e4ccc94441cd55ae8048cf55fc42df715d28b67cb80", upload-time = "2024-03-24T00:00:00Z" },
        ]
        "#
        );
    });

    uv_snapshot!(context.filters(), context.lock().arg("--locked"), @"
    exit_code: 0 (success)
    ----- stderr -----
    warning: Declaring conflicts for packages (`package = ...`) is experimental and may change without warning. Pass `--preview-features package-conflicts` to disable this warning.
    Resolved 4 packages in [TIME]
    ");

    uv_snapshot!(context.filters(), context.sync().arg("--frozen").arg("--all-packages"), @"
    exit_code: 2 (failure)
    ----- stderr -----
    error: Package `member-a` and package `member-b` are incompatible with the declared conflicts: {member-a, member-b}
    ");

    Ok(())
}

/// Locking a non-project workspace root should reject conflicts that omit
/// `package = ...`, since there is no root project name to infer.
#[cfg(feature = "test-universal")]
#[test]
fn lock_non_project_member_conflicts_missing_package() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [tool.uv.workspace]
        members = ["member-a"]

        [tool.uv]
        conflicts = [
          [
            { extra = "foo" },
            { package = "member-a" },
          ],
        ]
        "#,
    )?;

    let member_a = context.temp_dir.child("member-a");
    member_a.create_dir_all()?;
    member_a.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "member-a"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = []

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @r#"
    exit_code: 2 (failure)
    ----- stderr -----
    error: Expected `package` field in conflicting entry: { extra = "foo" }
    "#);

    Ok(())
}

/// `coverage` defines a `toml` extra, but it doesn't enable any dependencies after Python 3.11.
#[cfg(feature = "test-universal")]
#[test]
fn lock_dropped_dev_extra() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"

        [tool.uv]
        dev-dependencies = ["coverage[toml]"]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    warning: The `tool.uv.dev-dependencies` field (used in `pyproject.toml`) is deprecated and will be removed in a future release; use `dependency-groups.dev` instead
    Resolved 2 packages in [TIME]
    warning: The package `coverage==7.6.10` does not have an extra named `toml`
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "coverage"
        version = "7.6.10"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/coverage-7.6.10.tar.gz", hash = "sha256:c2c28f11a5434d50a208f3bb63fe5ba614d7f6a16b22d3003a974c98baf4d023", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/coverage-7.6.10-py3-none-any.whl", hash = "sha256:a4c3e496f8e510734007caeed72b92f2b96065e7e48e3bc0160019ebda221317", upload-time = "2024-03-24T00:00:00Z" },
        ]

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }

        [package.dev-dependencies]
        dev = [
            { name = "coverage" },
        ]

        [package.metadata]

        [package.metadata.requires-dev]
        dev = [{ name = "coverage", extras = ["toml"] }]
        "#
        );
    });

    // Re-run with `--locked`.
    uv_snapshot!(context.filters(), context.lock().arg("--locked"), @"
    exit_code: 0 (success)
    ----- stderr -----
    warning: The `tool.uv.dev-dependencies` field (used in `pyproject.toml`) is deprecated and will be removed in a future release; use `dependency-groups.dev` instead
    Resolved 2 packages in [TIME]
    ");

    // Re-run with `--offline`. We shouldn't need a network connection to validate an
    // already-correct lockfile with immutable metadata.
    uv_snapshot!(context.filters(), context.lock().arg("--locked").arg("--offline").arg("--no-cache"), @"
    exit_code: 0 (success)
    ----- stderr -----
    warning: The `tool.uv.dev-dependencies` field (used in `pyproject.toml`) is deprecated and will be removed in a future release; use `dependency-groups.dev` instead
    Resolved 2 packages in [TIME]
    ");

    // Install from the lockfile.
    uv_snapshot!(context.filters(), context.sync().arg("--frozen"), @"
    exit_code: 0 (success)
    ----- stderr -----
    warning: The `tool.uv.dev-dependencies` field (used in `pyproject.toml`) is deprecated and will be removed in a future release; use `dependency-groups.dev` instead
    Prepared 1 package in [TIME]
    Installed 1 package in [TIME]
     + coverage==7.6.10
    ");

    Ok(())
}

