#[cfg(feature = "test-universal")]
#[test]
fn lock_multiple_sources() -> Result<()> {
    let direct_artifacts = PackseServer::new("packages/lock-direct-artifacts.toml");
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(&format!(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["iniconfig"]

        [tool.uv.sources]
        iniconfig = [
            {{ url = "{iniconfig_wheel}", marker = "sys_platform != 'win32'" }},
            {{ url = "{iniconfig_sdist}", marker = "sys_platform == 'win32'" }},
        ]
        "#,
        iniconfig_wheel = direct_artifacts.file_url("iniconfig-2.0.0-py3-none-any.whl"),
        iniconfig_sdist = direct_artifacts.file_url("iniconfig-2.0.0.tar.gz"),
    ))?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 3 packages in [TIME]
    ");

    let lock = context.read("uv.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"
        resolution-markers = [
            "sys_platform != 'win32'",
            "sys_platform == 'win32'",
        ]

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "iniconfig"
        version = "2.0.0"
        source = { url = "http://[LOCALHOST]/files/iniconfig-2.0.0-py3-none-any.whl" }
        resolution-markers = [
            "sys_platform != 'win32'",
        ]
        wheels = [
            { url = "http://[LOCALHOST]/files/iniconfig-2.0.0-py3-none-any.whl", hash = "sha256:8a0fc44e516906bdecc91af1c3bc12134c9d1647a482446edc62f2f72191416c" },
        ]

        [[package]]
        name = "iniconfig"
        version = "2.0.0"
        source = { url = "http://[LOCALHOST]/files/iniconfig-2.0.0.tar.gz" }
        resolution-markers = [
            "sys_platform == 'win32'",
        ]
        sdist = { hash = "sha256:48c42a08c0ec1a24f2fe45f4efdefc9c19ac8e0aa8e82284503ccba80398bec3" }

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "iniconfig", version = "2.0.0", source = { url = "http://[LOCALHOST]/files/iniconfig-2.0.0-py3-none-any.whl" }, marker = "sys_platform != 'win32'" },
            { name = "iniconfig", version = "2.0.0", source = { url = "http://[LOCALHOST]/files/iniconfig-2.0.0.tar.gz" }, marker = "sys_platform == 'win32'" },
        ]

        [package.metadata]
        requires-dist = [
            { name = "iniconfig", marker = "sys_platform != 'win32'", url = "http://[LOCALHOST]/files/iniconfig-2.0.0-py3-none-any.whl" },
            { name = "iniconfig", marker = "sys_platform == 'win32'", url = "http://[LOCALHOST]/files/iniconfig-2.0.0.tar.gz" },
        ]
        "#
        );
    });

    // Re-run with `--locked`.
    uv_snapshot!(context.filters(), context.lock().arg("--locked"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 3 packages in [TIME]
    ");

    Ok(())
}

