/// Referring to a dependency-group with group-requires-python that does not exist
#[cfg(feature = "test-universal")]
#[test]
fn lock_group_requires_undefined_group() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "myproject"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["typing-extensions"]

        [dependency-groups]
        bar = ["sortedcontainers"]

        [tool.uv.dependency-groups]
        foo = { requires-python = ">=3.13" }
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 2 (failure)
    ----- stderr -----
    error: Project `myproject` has malformed dependency groups
      cause: Failed to find group `foo` specified in `[tool.uv.dependency-groups]`
    ");
    Ok(())
}

/// The legacy dev-dependencies cannot be referred to by group-requires-python
#[cfg(feature = "test-universal")]
#[test]
fn lock_group_requires_dev_dep() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "myproject"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["typing-extensions"]

        [tool.uv]
        dev-dependencies = ["sortedcontainers"]

        [tool.uv.dependency-groups]
        dev = { requires-python = ">=3.13" }
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 2 (failure)
    ----- stderr -----
    warning: The `tool.uv.dev-dependencies` field (used in `pyproject.toml`) is deprecated and will be removed in a future release; use `dependency-groups.dev` instead
    error: Project `myproject` has malformed dependency groups
      cause: `[tool.uv.dependency-groups]` specifies the `dev` group, but only `tool.uv.dev-dependencies` was found. To reference the `dev` group, remove the `tool.uv.dev-dependencies` section and add any development dependencies to the `dev` entry in the `[dependency-groups]` table instead.
    ");
    Ok(())
}

