#[cfg(feature = "test-universal")]
#[test]
fn lock_group_include_cycle() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["typing-extensions"]

        [dependency-groups]
        foo = ["anyio", {include-group = "bar"}]
        bar = [{include-group = "foobar"}]
        foobar = [{include-group = "foo"}]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 2 (failure)
    ----- stderr -----
    error: Project `project` has malformed dependency groups
      cause: Detected a cycle in `dependency-groups`: `bar` -> `foobar` -> `foo` -> `bar`
    ");

    Ok(())
}

