/// Repro for: <https://github.com/astral-sh/uv/issues/18312>
///
/// `uv lock --script` should invalidate a script lockfile when a local editable dependency's
/// `pyproject.toml` changes.
#[cfg(feature = "test-universal")]
#[test]
fn lock_script_editable_path_dependency_change() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let script = context.temp_dir.child("script.py");
    script.write_str(indoc! { r#"
        # /// script
        # requires-python = ">=3.11"
        # dependencies = [
        #   "child",
        # ]
        #
        # [tool.uv.sources]
        # child = { path = "child", editable = true }
        # ///

        import child
       "#
    })?;

    let child = context.temp_dir.child("child");
    fs_err::create_dir_all(&child)?;

    let child_pyproject_toml = child.child("pyproject.toml");
    child_pyproject_toml.write_str(
        r#"
        [project]
        name = "child"
        version = "0.1.0"
        requires-python = ">=3.11"
        dependencies = ["iniconfig"]

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    context
        .lock()
        .arg("--script")
        .arg("script.py")
        .assert()
        .success();

    let lock = context.read("script.py.lock");
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock,
            @r#"
        version = 1
        revision = 3
        requires-python = ">=3.11"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [manifest]
        requirements = [{ name = "child", editable = "child" }]

        [[package]]
        name = "child"
        version = "0.1.0"
        source = { editable = "child" }
        dependencies = [
            { name = "iniconfig" },
        ]

        [package.metadata]
        requires-dist = [{ name = "iniconfig" }]

        [[package]]
        name = "iniconfig"
        version = "2.0.0"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/iniconfig-2.0.0.tar.gz", hash = "sha256:48c42a08c0ec1a24f2fe45f4efdefc9c19ac8e0aa8e82284503ccba80398bec3", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/iniconfig-2.0.0-py3-none-any.whl", hash = "sha256:8a0fc44e516906bdecc91af1c3bc12134c9d1647a482446edc62f2f72191416c", upload-time = "2024-03-24T00:00:00Z" },
        ]
        "#
        );
    });

    context
        .lock()
        .arg("--script")
        .arg("script.py")
        .arg("--locked")
        .assert()
        .success();

    // Update the editable dependency's transitive requirements.
    child_pyproject_toml.write_str(
        r#"
        [project]
        name = "child"
        version = "0.1.0"
        requires-python = ">=3.11"
        dependencies = ["sniffio"]

        [build-system]
        requires = ["uv_build>=0.7,<10000"]
        build-backend = "uv_build"
        "#,
    )?;

    // Expected behavior: this should fail because the script lockfile is stale.
    let output = context
        .lock()
        .arg("--script")
        .arg("script.py")
        .arg("--locked")
        .output()?;
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        !output.status.success(),
        "expected `uv lock --script script.py --locked` to fail after editable dependency changes, but it succeeded\n{stderr}"
    );
    assert!(stderr.contains("needs to be updated"), "{stderr}");

    // Expected behavior: re-locking should pick up the new transitive dependency.
    context
        .lock()
        .arg("--script")
        .arg("script.py")
        .assert()
        .success();
    let lock = context.read("script.py.lock");
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock,
            @r#"
        version = 1
        revision = 3
        requires-python = ">=3.11"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [manifest]
        requirements = [{ name = "child", editable = "child" }]

        [[package]]
        name = "child"
        version = "0.1.0"
        source = { editable = "child" }
        dependencies = [
            { name = "sniffio" },
        ]

        [package.metadata]
        requires-dist = [{ name = "sniffio" }]

        [[package]]
        name = "sniffio"
        version = "1.3.1"
        source = { registry = "http://[LOCALHOST]/simple/" }
        sdist = { url = "http://[LOCALHOST]/files/sniffio-1.3.1.tar.gz", hash = "sha256:ce520d2eb3c2be02f0c148dab5ba304e8705e1c7e7b4bec8a9146c464a597a6a", upload-time = "2024-03-24T00:00:00Z" }
        wheels = [
            { url = "http://[LOCALHOST]/files/sniffio-1.3.1-py3-none-any.whl", hash = "sha256:2743fa2a853c508a2310882c0b4104631e0b0fcb855e00a912b7e3f27e6b3f05", upload-time = "2024-03-24T00:00:00Z" },
        ]
        "#
        );
    });

    Ok(())
}

/// `uv lock --script` should add a PEP 723 tag, if it doesn't exist already.
#[cfg(feature = "test-universal")]
#[test]
fn lock_script_initialize() -> Result<()> {
    let context = uv_test::test_context!("3.12").with_filtered_missing_file_error();

    uv_snapshot!(context.filters(), context.lock().arg("--script").arg("script.py"), @"
    exit_code: 2 (failure)
    ----- stderr -----
    error: failed to read from file `script.py`: [OS ERROR 2]
    ");

    let script = context.temp_dir.child("script.py");
    script.write_str(indoc! { r"
        print('Hello, world!')
       "
    })?;

    uv_snapshot!(context.filters(), context.lock().arg("--script").arg("script.py"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved in [TIME]
    ");

    let lock = context.read("script.py.lock");

    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"
        "#
        );
    });

    Ok(())
}

