#[cfg(feature = "test-universal")]
#[test]
fn lock_trailing_slash_find_links() -> Result<()> {
    let context = uv_test::test_context!("3.12");
    let vendor = uv_test::find_links::FindLinksServer::new_at_path(
        &context.workspace_root.join("test/vendor"),
        "/simple/packaging",
    );
    let find_links_url = vendor.url();

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(&formatdoc!(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["packaging==23.2"]
        [tool.uv]
        no-index = true
        find-links = ["{find_links_url}"]
        "#,
    ))?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    let lock = context.read("uv.lock");
    insta::with_settings!({
            filters => context.filters(),
    }, {
            assert_snapshot!(
                lock, @r#"
            version = 1
            revision = 3
            requires-python = ">=3.12"

            [options]
            exclude-newer = "2024-03-25T00:00:00Z"

            [[package]]
            name = "packaging"
            version = "23.2"
            source = { registry = "http://[LOCALHOST]/simple/packaging" }
            sdist = { url = "http://[LOCALHOST]/packaging-23.2.tar.gz" }
            wheels = [
                { url = "http://[LOCALHOST]/packaging-23.2-py3-none-any.whl" },
            ]

            [[package]]
            name = "project"
            version = "0.1.0"
            source = { virtual = "." }
            dependencies = [
                { name = "packaging" },
            ]

            [package.metadata]
            requires-dist = [{ name = "packaging", specifier = "==23.2" }]
            "#
        );
    });

    // Re-run with `--locked`.
    uv_snapshot!(context.filters(), context.lock().arg("--locked"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    // Add a trailing slash, which should invalidate the lockfile
    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(&formatdoc!(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["packaging==23.2"]
        [tool.uv]
        no-index = true
        find-links = ["{find_links_url}/"]
        "#,
    ))?;

    // Re-run with `--locked`
    uv_snapshot!(context.filters(), context.lock().arg("--locked"), @"
    exit_code: 1 (failure)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    error: The lockfile at `uv.lock` needs to be updated, but `--locked` was provided.

    hint: To update the lockfile, run `uv lock`.
    ");

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    let lock = context.read("uv.lock");
    insta::with_settings!({
        filters => context.filters(),
    }, {
        assert_snapshot!(
            lock, @r#"
        version = 1
        revision = 3
        requires-python = ">=3.12"

        [options]
        exclude-newer = "2024-03-25T00:00:00Z"

        [[package]]
        name = "packaging"
        version = "23.2"
        source = { registry = "http://[LOCALHOST]/simple/packaging/" }
        sdist = { url = "http://[LOCALHOST]/packaging-23.2.tar.gz" }
        wheels = [
            { url = "http://[LOCALHOST]/packaging-23.2-py3-none-any.whl" },
        ]

        [[package]]
        name = "project"
        version = "0.1.0"
        source = { virtual = "." }
        dependencies = [
            { name = "packaging" },
        ]

        [package.metadata]
        requires-dist = [{ name = "packaging", specifier = "==23.2" }]
        "#
        );
    });

    Ok(())
}

#[cfg(feature = "test-universal")]
#[test]
fn lock_prefix_match() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = ["anyio==5.4.*"]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 1 (failure)
    ----- stderr -----
    error: No solution found when resolving dependencies
      cause: Because only anyio<=4.3.0 is available and your project depends on anyio==5.4.*, we can conclude that your project's requirements are unsatisfiable.
    ");

    Ok(())
}

/// Regression test for <https://github.com/astral-sh/uv/issues/14231>.
#[cfg(feature = "test-universal")]
#[test]
fn test_tilde_equals_python_version() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "debug"
        version = "0.1.0"
        requires-python = ">=3.9"
        dependencies = [
          "anyio==4.2.0; python_full_version >= '3.11'",
          "anyio==4.3.0; python_full_version ~= '3.10.0'",
        ]
    "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 7 packages in [TIME]
    ");

    Ok(())
}

