#[cfg(feature = "test-universal")]
#[test]
fn lock_refresh_deindents_lockfile() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    context.temp_dir.child("pyproject.toml").write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = [
            "sniffio"
        ]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    let original_lock = context.read("uv.lock");
    let dedented_lock = original_lock
        .lines()
        .map(str::trim_start)
        .collect::<Vec<_>>()
        .join("\n");
    context
        .temp_dir
        .child("uv.lock")
        .write_str(&dedented_lock)?;

    uv_snapshot!(context.filters(), context.lock().arg("--check").arg("--preview-features").arg("lockfile-format-check"), @"
    exit_code: 1 (failure)
    ----- stderr -----
    error: The lockfile at `uv.lock` has non-canonical formatting at line 13, but `--check` was provided.

    hint: To regenerate the lockfile, run `uv lock --refresh --preview-features lockfile-format-check`.
    ");

    uv_snapshot!(context.filters(), context.lock().arg("--refresh").arg("--dry-run"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    No lockfile changes detected
    ");
    assert_eq!(context.read("uv.lock"), dedented_lock);

    uv_snapshot!(context.filters(), context.lock().arg("--refresh"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");
    assert_eq!(context.read("uv.lock"), dedented_lock);

    uv_snapshot!(context.filters(), context.lock().arg("--refresh").arg("--dry-run").arg("--preview-features").arg("lockfile-format-check"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    Lockfile changes detected
    ");
    assert_eq!(context.read("uv.lock"), dedented_lock);

    uv_snapshot!(context.filters(), context.lock().arg("--refresh").arg("--preview-features").arg("lockfile-format-check"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");
    insta::with_settings!({ filters => context.filters() }, {
    assert_snapshot!(context.read("uv.lock"), @r#"
    version = 1
    revision = 3
    requires-python = ">=3.12"

    [options]
    exclude-newer = "2024-03-25T00:00:00Z"

    [[package]]
    name = "project"
    version = "0.1.0"
    source = { virtual = "." }
    dependencies = [
        { name = "sniffio" },
    ]

    [package.metadata]
    requires-dist = [{ name = "sniffio" }]

    [[package]]
    name = "sniffio"
    version = "1.3.1"
    source = { registry = "http://[LOCALHOST]/simple/" }
    sdist = { url = "http://[LOCALHOST]/files/sniffio-1.3.1.tar.gz", hash = "sha256:ce520d2eb3c2be02f0c148dab5ba304e8705e1c7e7b4bec8a9146c464a597a6a", upload-time = "2024-03-24T00:00:00Z" }
    wheels = [
        { url = "http://[LOCALHOST]/files/sniffio-1.3.1-py3-none-any.whl", hash = "sha256:2743fa2a853c508a2310882c0b4104631e0b0fcb855e00a912b7e3f27e6b3f05", upload-time = "2024-03-24T00:00:00Z" },
    ]
    "#);
    });

    uv_snapshot!(context.filters(), context.lock().arg("--check").arg("--preview-features").arg("lockfile-format-check"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    ");

    uv_snapshot!(context.filters(), context.lock().arg("--refresh").arg("--dry-run").arg("--preview-features").arg("lockfile-format-check"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 2 packages in [TIME]
    No lockfile changes detected
    ");

    Ok(())
}

/// Ensure conflicts on virtual packages (such as markers) give good error messages.
#[cfg(feature = "test-universal")]
#[test]
fn collapsed_error_with_marker_packages() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = indoc! {r#"
        [project]
        name = "test-project"
        version = "1.0.0"
        requires-python = ">=3.12"
        dependencies = [
            "anyio<=4.3.0; sys_platform == 'other'",
            "anyio>=4.4.0; python_version < '3.14'",
        ]
    "#};
    context
        .temp_dir
        .child("pyproject.toml")
        .write_str(pyproject_toml)?;

    uv_snapshot!(context.filters(), context.lock(), @"
    exit_code: 1 (failure)
    ----- stderr -----
    error: No solution found when resolving dependencies for split (markers: python_full_version < '3.14' and sys_platform == 'other')
      cause: Because your project depends on anyio{sys_platform == 'other'} and anyio{python_full_version < '3.14'}>=4.4.0, we can conclude that your project's requirements are unsatisfiable.

    hint: The resolution failed for an environment that is not the current one, consider limiting the environments with `tool.uv.environments`.
    ");

    Ok(())
}

/// <https://github.com/astral-sh/uv/issues/16148>
#[cfg(feature = "test-universal")]
#[test]
fn no_warning_without_and_with_lower_bound() -> Result<()> {
    let context = uv_test::test_context!("3.12");

    let pyproject_toml = context.temp_dir.child("pyproject.toml");
    pyproject_toml.write_str(
        r#"
        [project]
        name = "project"
        version = "0.1.0"
        requires-python = ">=3.12"
        dependencies = [
            "anyio[trio]",
            "anyio>=4"
        ]
        "#,
    )?;

    uv_snapshot!(context.filters(), context.lock().arg("--resolution").arg("lowest-direct"), @"
    exit_code: 0 (success)
    ----- stderr -----
    Resolved 10 packages in [TIME]
    ");

    Ok(())
}

